parameters.functionCode:
const response = $input.first().json.body;

const parsed = {
  respondent_email: response.email || response.respondent_email || '',
  respondent_name: response.name || response.respondent_name || 'Anonymous',
  submission_time: new Date().toISOString(),
  category: response.category || response.type || 'general',
  priority: response.priority || response.urgency || 'normal',
  subject: response.subject || response.title || 'No subject',
  details: response.details || response.message || response.description || '',
  rating: response.rating ? parseInt(response.rating) : null
};

parsed.is_urgent = parsed.priority.toLowerCase() === 'urgent' || 
                   parsed.priority.toLowerCase() === 'high' ||
                   (parsed.rating !== null && parsed.rating <= 2);

return [{ json: parsed }];

